    statement:{ru:"Имя Исаак означает «смех».",en:"The name Isaac means “laughter.”",de:"Der Name Isaak bedeutet „Lachen“.",es:"El nombre Isaac significa «risa».",pt:"O nome Isaque significa “riso”.",fr:"Le nom Isaac signifie « rire ».",ar:"اسم إسحاق يعني «ضحك»."}, truth:true,
